MERGE `{{params.project_name}}.semantics_central.Dealers` final
USING (
{{range_query}}
) staging
ON final.dealer_id = staging.dealer_id
WHEN MATCHED THEN
UPDATE SET
final.dealer_name = staging.dealer_name,
final.dealer_email = staging.dealer_email,
final.dealer_number_of_favorites = staging.dealer_number_of_favorites,
final.is_internal = staging.is_internal,
final.dealer_created = staging.dealer_created,
final.dealer_last_modified = staging.dealer_last_modified,
final.dealer_company_name = staging.dealer_company_name,
final.number_of_auctions = staging.number_of_auctions,
final.number_of_win_auctions = staging.number_of_win_auctions,
final.number_of_bids = staging.number_of_bids,
/* final.last_login = staging.last_login, */
final.last_bid_placed = staging.last_bid_placed,
final.deleted_at = staging.deleted_at,
final.country_id = staging.country_id,
final.dealer_status = staging.dealer_status,
final.dealer_manager_id = staging.dealer_manager_id,
final.dealer_manager_name = staging.dealer_manager_name,
final.dealer_company_legal_name = staging.dealer_company_legal_name,
final.dealer_company_legal_tax = staging.dealer_company_legal_tax,
final.dealer_tax_id = staging.dealer_tax_id,
final.dealer_address = staging.dealer_address,
final.dealer_city = staging.dealer_city,
final.dealer_phone = staging.dealer_phone,
final.dealer_zip_code = staging.dealer_zip_code,
final.max_amount_of_bids = staging.max_amount_of_bids,
final.blocked_reason = staging.blocked_reason,
final.dealer_category = staging.dealer_category,
final.dealer_size = staging.dealer_size,
final.registration_id = staging.registration_id,
final.tax_office = staging.tax_office,
final.authorized_pickup_persons = staging.authorized_pickup_persons,
final.payment_terms = staging.payment_terms,
final.bank_details = staging.bank_details,
final.dealer_comments = staging.dealer_comments,
final.internal_id = staging.internal_id,
final.dealer_number = staging.dealer_number,
final.dealer_login = staging.dealer_login,
final.dealer_cms_status = staging.dealer_cms_status,
final.system_set_credit_limit = staging.system_set_credit_limit,
final.system_set_deposit_amount = staging.system_set_deposit_amount,
final.dealer_bid_manager = staging.dealer_bid_manager,
final.meta_info = staging.meta_info
WHEN NOT MATCHED THEN
INSERT (
dealer_id,
dealer_name,
dealer_email,
dealer_number_of_favorites,
is_internal,
dealer_created,
dealer_last_modified,
dealer_company_name,
number_of_auctions,
number_of_win_auctions,
number_of_bids,
/* last_login, */
last_bid_placed,
deleted_at,
country_id,
dealer_status,
dealer_manager_id,
dealer_manager_name,
dealer_company_legal_name,
dealer_company_legal_tax,
dealer_tax_id,
dealer_address,
dealer_city,
dealer_phone,
dealer_zip_code,
max_amount_of_bids,
blocked_reason,
dealer_category,
dealer_size,
registration_id,
tax_office,
authorized_pickup_persons,
payment_terms,
bank_details,
dealer_comments,
internal_id,
dealer_number,
dealer_login,
dealer_cms_status,
system_set_credit_limit,
system_set_deposit_amount,
dealer_bid_manager,
meta_info
) VALUES (
staging.dealer_id,
staging.dealer_name,
staging.dealer_email,
staging.dealer_number_of_favorites,
staging.is_internal,
staging.dealer_created,
staging.dealer_last_modified,
staging.dealer_company_name,
staging.number_of_auctions,
staging.number_of_win_auctions,
staging.number_of_bids,
/* staging.last_login, */
staging.last_bid_placed,
staging.deleted_at,
staging.country_id,
staging.dealer_status,
staging.dealer_manager_id,
staging.dealer_manager_name,
staging.dealer_company_legal_name,
staging.dealer_company_legal_tax,
staging.dealer_tax_id,
staging.dealer_address,
staging.dealer_city,
staging.dealer_phone,
staging.dealer_zip_code,
staging.max_amount_of_bids,
staging.blocked_reason,
staging.dealer_category,
staging.dealer_size,
staging.registration_id,
staging.tax_office,
staging.authorized_pickup_persons,
staging.payment_terms,
staging.bank_details,
staging.dealer_comments,
staging.internal_id,
staging.dealer_number,
staging.dealer_login,
staging.dealer_cms_status,
staging.system_set_credit_limit,
staging.system_set_deposit_amount,
staging.dealer_bid_manager,
staging.meta_info
)